<script setup>
import { ref, watch, nextTick, onBeforeUnmount } from 'vue'
import * as echarts from 'echarts'
import { useAppStore } from '../stores/app'
import api from '../api/client'
import { checkpointMatches } from '../utils/dispatchAlgorithms'
const app=useAppStore(), preset=ref('default'), seeds=ref('1042, 1043, 1044, 1045, 1046'), methods=ref(['shortest_fastest','greedy_estimate']), checkpoints=ref([]), result=ref(null), loading=ref(false), chartEl=ref(null); let chart
const fields=[['综合得分','objective_score'],['任务完成率','task_success_rate'],['超时率','deadline_miss_rate'],['平均时延','avg_delay_s'],['平均能耗','avg_energy_j'],['负载方差','mean_load_variance'],['平均跳数','mean_hops_accepted'],['DAG Makespan','avg_dag_makespan_s'],['CPU 负载标准差','cpu_load_std'],['NPU 负载标准差','npu_load_std'],['FPGA 负载标准差','fpga_load_std'],['FPGA 重构率','fpga_reconfig_rate']]
watch(preset, () => { checkpoints.value = []; methods.value = methods.value.filter(m => m !== 'heft_hetero') })
async function evaluate(){ loading.value=true; try { const config=preset.value==='draft' ? app.env : {preset_name:preset.value,config:{}}; result.value=await api.post('/experiments/evaluate',{...config,seeds:seeds.value.split(/[,，\s]+/).filter(Boolean).map(Number),strategies:[...methods.value.map(method=>({method})),...checkpoints.value.map(path=>({method:'checkpoint',name:path.split('/').slice(-2).join('/'),checkpoint_path:path}))],persist:false}); await nextTick(); if(!chart) chart=echarts.init(chartEl.value); chart.setOption({color:['#42bdf2','#56dfab','#ffbd63','#a79eff','#ef8ca8','#5ce5e0','#8eaaff'],textStyle:{color:'#b4cee7'},tooltip:{trigger:'axis'},legend:{bottom:0,textStyle:{color:'#b4cee7'}},grid:{top:25,bottom:75,left:55,right:20},xAxis:{type:'category',data:result.value.strategies.map(s=>s.name),axisLabel:{interval:0,rotate:15}},yAxis:{type:'value',scale:true,splitLine:{lineStyle:{color:'#194363'}}},series:fields.map(([name,key])=>({name,type:'bar',data:result.value.strategies.map(s=>s.summary[key+'_mean'])}))},true) } finally { loading.value=false } }
onBeforeUnmount(()=>chart?.dispose())
</script>
<template><div class="page"><div class="page-head"><div><div class="eyebrow">COMPARISON LAB</div><h1>多算法对比评估</h1><p>在相同场景和随机种子下比较调度策略。</p></div><div class="page-code">策略评估 / 03</div></div><div class="compare-layout"><section class="panel"><div class="panel-heading"><div><div class="eyebrow">EVALUATION SETUP</div><h3>评估配置</h3></div></div><div class="vertical-form"><label>测试场景<el-select v-model="preset"><el-option label="工作台当前草稿" value="draft"/><el-option v-for="p in Object.keys(app.presets)" :key="p" :value="p"/></el-select></label><label>评估随机种子<el-input v-model="seeds" placeholder="用逗号分隔"/></label><label>启发式策略<el-checkbox-group v-model="methods"><el-checkbox label="shortest_fastest">最短最快</el-checkbox><el-checkbox label="greedy_estimate">贪心估计</el-checkbox><el-checkbox v-if="(preset === 'draft' ? app.env?.config : app.presets[preset])?.enable_dag_mode" label="heft_hetero">异构 HEFT</el-checkbox></el-checkbox-group></label><label>模型 Checkpoint<el-select v-model="checkpoints" multiple filterable collapse-tags placeholder="选择一个或多个模型"><el-option v-for="c in app.checkpoints.filter(c => checkpointMatches(c, preset === 'draft' ? app.env?.config : app.presets[preset]))" :key="c.path" :label="c.run_dir+' / '+c.name" :value="c.path"/></el-select></label><el-button type="primary" :loading="loading" @click="evaluate">运行对比评估</el-button></div></section><section class="panel result-panel"><div class="panel-heading"><div><div class="eyebrow">RESULTS</div><h3>策略指标对比</h3></div><span class="chip">多种子均值</span></div><template v-if="result"><div ref="chartEl" class="compare-chart"></div><el-table :data="result.strategies" size="small"><el-table-column prop="name" label="策略" min-width="150"/><el-table-column v-for="f in fields" :key="f[1]" :label="f[0]" min-width="100"><template #default="{row}">{{ row.summary[f[1]+'_mean'] == null ? '—' : Number(row.summary[f[1]+'_mean']).toFixed(4) }}</template></el-table-column></el-table></template><el-empty v-else description="运行评估后查看对比结果" /></section></div></div></template>
